(12, 8, '_dvg_visa_types', 'a:4:{i:0;a:5:{s:4:\"name\";s:19:\"30-Day Tourist Visa\";s:3:\"fee\";s:3:\"$90\";s:4:\"time\";s:10:\"3–4 days\";s:8:\"validity\";s:7:\"30 days\";s:4:\"desc\";s:58:\"Single-entry tourist visa, extendable once inside the UAE.\";}i:1;a:5:{s:4:\"name\";s:19:\"60-Day Tourist Visa\";s:3:\"fee\";s:4:\"$160\";s:4:\"time\";s:10:\"3–5 days\";s:8:\"validity\";s:7:\"60 days\";s:4:\"desc\";s:55:\"Longer stay for tourism or visiting family and friends.\";}i:2;a:5:{s:4:\"name\";s:19:\"Multiple-Entry Visa\";s:3:\"fee\";s:4:\"$320\";s:4:\"time\";s:10:\"4–6 days\";s:8:\"validity\";s:7:\"5 years\";s:4:\"desc\";s:50:\"Frequent travellers; stay up to 90 days per visit.\";}i:3;a:5:{s:4:\"name\";s:12:\"Transit Visa\";s:3:\"fee\";s:3:\"$35\";s:4:\"time\";s:11:\"24–48 hrs\";s:8:\"validity\";s:11:\"48 / 96 hrs\";s:4:\"desc\";s:51:\"For short layovers connecting through UAE airports.\";}}'),
(13, 8, '_dvg_documents', 'Passport valid for at least 6 months\r\nColoured passport-size photograph (white background)\r\nConfirmed return flight ticket\r\nHotel booking or host details\r\nBank statement (last 3 months)'),
(14, 8, '_dvg_faqs', 'a:3:{i:0;a:2:{s:1:\"q\";s:34:\"Can I apply for a UAE visa online?\";s:1:\"a\";s:94:\"Yes. Most nationalities can apply for the UAE eVisa completely online and receive it by email.\";}i:1;a:2:{s:1:\"q\";s:39:\"How long does UAE visa processing take?\";s:1:\"a\";s:96:\"Standard processing takes 3–5 working days. Express options are available for some visa types.\";}i:2;a:2:{s:1:\"q\";s:33:\"Can I extend my UAE tourist visa?\";s:1:\"a\";s:98:\"Yes, the 30-day and 60-day tourist visas can usually be extended once without exiting the country.\";}}'),
(15, 8, '_dvg_embassy', 'UAE Embassy & Visa Services\r\nVisa support: Mon–Sat 9:00–18:00\r\nApply online via the official ICP / GDRFA portals.\r\nFor assistance, message us on WhatsApp.'),
(16, 9, '_dvg_flag', '🇨🇦'),
(17, 9, '_dvg_visa_required', 'yes'),
(18, 9, '_dvg_processing', '4 – 8 weeks'),
(19, 9, '_dvg_fee_from', 'From $100'),
(20, 9, '_dvg_validity', 'Up to 10 years'),
(21, 9, '_dvg_entry', 'Single / Multiple'),
(22, 9, '_dvg_featured', '1'),
(23, 9, '_dvg_visa_types', 'a:4:{i:0;a:5:{s:4:\"name\";s:18:\"Visitor Visa (TRV)\";s:3:\"fee\";s:4:\"$100\";s:4:\"time\";s:11:\"4–6 weeks\";s:8:\"validity\";s:12:\"Up to 10 yrs\";s:4:\"desc\";s:53:\"For tourism, visiting family or short business trips.\";}i:1;a:5:{s:4:\"name\";s:37:\"eTA (Electronic Travel Authorization)\";s:3:\"fee\";s:2:\"$7\";s:4:\"time\";s:16:\"Minutes–72 hrs\";s:8:\"validity\";s:7:\"5 years\";s:4:\"desc\";s:43:\"For visa-exempt travellers arriving by air.\";}i:2;a:5:{s:4:\"name\";s:12:\"Study Permit\";s:3:\"fee\";s:4:\"$110\";s:4:\"time\";s:12:\"6–12 weeks\";s:8:\"validity\";s:13:\"Course length\";s:4:\"desc\";s:55:\"For international students with a letter of acceptance.\";}i:3;a:5:{s:4:\"name\";s:11:\"Work Permit\";s:3:\"fee\";s:4:\"$120\";s:4:\"time\";s:12:\"8–16 weeks\";s:8:\"validity\";s:12:\"Per contract\";s:4:\"desc\";s:39:\"Employer-specific or open work permits.\";}}'),
(24, 9, '_dvg_documents', 'Passport valid for the duration of stay\r\nDigital photograph meeting IRCC specs\r\nProof of funds / bank statements\r\nLetter of invitation (if applicable)\r\nTravel itinerary and purpose of visit\r\nBiometrics (fingerprints & photo)'),
(25, 9, '_dvg_faqs', 'a:3:{i:0;a:2:{s:1:\"q\";s:39:\"Do I need biometrics for a Canada visa?\";s:1:\"a\";s:104:\"Most applicants aged 14–79 must give biometrics (fingerprints and photo) at a Visa Application Centre.\";}i:1;a:2:{s:1:\"q\";s:15:\"What is an eTA?\";s:1:\"a\";s:121:\"An Electronic Travel Authorization is required for visa-exempt nationals flying to Canada. It is linked to your passport.\";}i:2;a:2:{s:1:\"q\";s:38:\"How long can I stay on a visitor visa?\";s:1:\"a\";s:78:\"Usually up to 6 months per entry, as decided by the border officer on arrival.\";}}'),
(26, 9, '_dvg_embassy', 'High Commission of Canada\r\nApplications via IRCC & VFS Global centres.\r\nProcessing times vary by country.\r\nWhatsApp us for document checklists.'),
(27, 10, '_dvg_flag', '🇬🇧'),
(28, 10, '_dvg_visa_required', 'yes'),
(29, 10, '_dvg_processing', '3 weeks (standard)'),
(30, 10, '_dvg_fee_from', 'From $115'),
(31, 10, '_dvg_validity', '6 months – 10 years'),
(32, 10, '_dvg_entry', 'Single / Multiple'),
(33, 10, '_dvg_featured', '1'),
(34, 10, '_dvg_visa_types', 'a:4:{i:0;a:5:{s:4:\"name\";s:21:\"Standard Visitor Visa\";s:3:\"fee\";s:4:\"$115\";s:4:\"time\";s:7:\"3 weeks\";s:8:\"validity\";s:8:\"6 months\";s:4:\"desc\";s:48:\"Tourism, family visits and short business trips.\";}i:1;a:5:{s:4:\"name\";s:22:\"Long-term Visitor Visa\";s:3:\"fee\";s:4:\"$435\";s:4:\"time\";s:7:\"3 weeks\";s:8:\"validity\";s:14:\"2 / 5 / 10 yrs\";s:4:\"desc\";s:41:\"Multiple entries for frequent travellers.\";}i:2;a:5:{s:4:\"name\";s:12:\"Student Visa\";s:3:\"fee\";s:4:\"$610\";s:4:\"time\";s:7:\"3 weeks\";s:8:\"validity\";s:13:\"Course length\";s:4:\"desc\";s:48:\"For students with a CAS from a licensed sponsor.\";}i:3;a:5:{s:4:\"name\";s:19:\"Skilled Worker Visa\";s:3:\"fee\";s:9:\"From $920\";s:4:\"time\";s:7:\"3 weeks\";s:8:\"validity\";s:11:\"Up to 5 yrs\";s:4:\"desc\";s:53:\"For workers with a job offer from a licensed sponsor.\";}}'),
(35, 10, '_dvg_documents', 'Passport valid for your whole stay\r\nProof of funds to cover your trip\r\nAccommodation and travel details\r\nLetter of invitation (if visiting)\r\nTuberculosis test certificate (if required)\r\nSponsor / CAS reference (study & work)'),
(36, 10, '_dvg_faqs', 'a:3:{i:0;a:2:{s:1:\"q\";s:29:\"How fast can I get a UK visa?\";s:1:\"a\";s:143:\"Standard processing is around 3 weeks. Priority (5 working days) and super-priority (next working day) services are available for an extra fee.\";}i:1;a:2:{s:1:\"q\";s:38:\"Can I work on a Standard Visitor visa?\";s:1:\"a\";s:90:\"No. The visitor visa does not permit paid work. You need a work visa route for employment.\";}i:2;a:2:{s:1:\"q\";s:20:\"Do I need a TB test?\";s:1:\"a\";s:96:\"Applicants from certain countries staying more than 6 months must provide a TB test certificate.\";}}'),
(37, 10, '_dvg_embassy', 'UK Visas & Immigration (UKVI)\r\nApplications via VFS Global / TLScontact.\r\nBiometrics taken at a visa centre.\r\nNeed help? Message us on WhatsApp.'),
(38, 11, '_dvg_flag', '🇦🇺'),
(39, 11, '_dvg_visa_required', 'evisa'),
(40, 11, '_dvg_processing', '2 – 4 weeks'),
(41, 11, '_dvg_fee_from', 'From AUD 200'),
(42, 11, '_dvg_validity', '12 months'),
(43, 11, '_dvg_entry', 'Single / Multiple'),
(44, 11, '_dvg_featured', '1'),
(45, 11, '_dvg_visa_types', 'a:4:{i:0;a:5:{s:4:\"name\";s:27:\"Visitor Visa (Subclass 600)\";s:3:\"fee\";s:7:\"AUD 200\";s:4:\"time\";s:11:\"2–4 weeks\";s:8:\"validity\";s:11:\"Up to 12 mo\";s:4:\"desc\";s:55:\"Tourism, family visits and business visitor activities.\";}i:1;a:5:{s:4:\"name\";s:23:\"eVisitor (Subclass 651)\";s:3:\"fee\";s:4:\"Free\";s:4:\"time\";s:10:\"1–5 days\";s:8:\"validity\";s:9:\"12 months\";s:4:\"desc\";s:39:\"For eligible European passport holders.\";}i:2;a:5:{s:4:\"name\";s:18:\"ETA (Subclass 601)\";s:3:\"fee\";s:6:\"AUD 15\";s:4:\"time\";s:14:\"Minutes–days\";s:8:\"validity\";s:9:\"12 months\";s:4:\"desc\";s:51:\"Electronic Travel Authority for eligible passports.\";}i:3;a:5:{s:4:\"name\";s:27:\"Student Visa (Subclass 500)\";s:3:\"fee\";s:8:\"AUD 2000\";s:4:\"time\";s:11:\"4–6 weeks\";s:8:\"validity\";s:13:\"Course length\";s:4:\"desc\";s:150:\"The safest source is the Australian Department of Home Affairs Visa Pricing Estimator:\r\n\r\nhttps://immi.homeaffairs.gov.au/visas/visa-pricing-estimator\";}}'),
(46, 11, '_dvg_documents', 'Passport valid for your stay\r\nRecent passport-style photograph\r\nProof of sufficient funds\r\nConfirmation of Enrolment (students)\r\nHealth insurance (OSHC for students)\r\nGenuine visitor / GTE statement'),
(47, 11, '_dvg_faqs', 'a:3:{i:0;a:2:{s:1:\"q\";s:38:\"Is the Australian visa applied online?\";s:1:\"a\";s:106:\"Yes. Australia uses a fully electronic system — there are no visa labels. You apply through ImmiAccount.\";}i:1;a:2:{s:1:\"q\";s:48:\"What is the difference between ETA and eVisitor?\";s:1:\"a\";s:144:\"Both are for short tourist/business stays but depend on your passport. ETA suits passports like the USA and Japan; eVisitor is for EU passports.\";}i:2;a:2:{s:1:\"q\";s:33:\"How long can I stay as a tourist?\";s:1:\"a\";s:74:\"Typically up to 3, 6 or 12 months per entry depending on the visa granted.\";}}'),
(48, 11, '_dvg_embassy', 'Department of Home Affairs (Australia)\r\nApply online via ImmiAccount.\r\nNo physical visa label is issued.\r\nWhatsApp us for eligibility help.'),
