INSERT INTO `wpek_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(44, 1, '2026-07-25 19:35:54', '0000-00-00 00:00:00', 'add_action(\'admin_init\', function () {\r\n    // Redirect any user trying to access comments page\r\n    global $pagenow;\r\n    \r\n    if ($pagenow === \'edit-comments.php\') {\r\n        wp_safe_redirect(admin_url());\r\n        exit;\r\n    }\r\n\r\n    // Remove comments metabox from dashboard\r\n    remove_meta_box(\'dashboard_recent_comments\', \'dashboard\', \'normal\');\r\n\r\n    // Disable support for comments and trackbacks in post types\r\n    foreach (get_post_types() as $post_type) {\r\n        if (post_type_supports($post_type, \'comments\')) {\r\n            remove_post_type_support($post_type, \'comments\');\r\n            remove_post_type_support($post_type, \'trackbacks\');\r\n        }\r\n    }\r\n});\r\n\r\n// Close comments on the front-end\r\nadd_filter(\'comments_open\', \'__return_false\', 20, 2);\r\nadd_filter(\'pings_open\', \'__return_false\', 20, 2);\r\n\r\n// Hide existing comments\r\nadd_filter(\'comments_array\', \'__return_empty_array\', 10, 2);\r\n\r\n// Remove comments page in menu\r\nadd_action(\'admin_menu\', function () {\r\n    remove_menu_page(\'edit-comments.php\');\r\n});\r\n\r\n// Remove comments links from admin bar\r\nadd_action(\'init\', function () {\r\n    if (is_admin_bar_showing()) {\r\n        remove_action(\'admin_bar_menu\', \'wp_admin_bar_comments_menu\', 60);\r\n    }\r\n});', 'Completely Disable Comments', '', 'draft', 'closed', 'closed', '', '', '', '', '2026-07-25 19:35:54', '0000-00-00 00:00:00', '', 0, 'https://dreamvisaguide.com/?post_type=wpcode&p=44', 0, 'wpcode', '', 0),
(52, 1, '2026-08-12 09:05:39', '2026-08-12 09:05:39', '<p class=\"isSelectedEnd\">The United Kingdom offers several visa and immigration routes for people who want to visit, study, work, join family members, establish a business, or settle in the UK.</p>\n<p class=\"isSelectedEnd\">The correct UK visa depends on your purpose of travel, nationality, qualifications, employment, financial circumstances, family relationship, and intended length of stay.</p>\n<p>At Dream Visa Guide, we provide general information about UK visa categories, eligibility requirements, required documents, application procedures, and important immigration considerations.</p>\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'United Kingdom', 'Standard Visitor, Student and Skilled Worker visas. Priority and super-priority options available.', 'inherit', 'closed', 'closed', '', '10-autosave-v1', '', '', '2026-08-12 09:05:39', '2026-08-12 09:05:39', '', 10, 'https://dreamvisaguide.com/?p=52', 0, 'revision', '', 0),
(54, 1, '2026-08-17 06:22:25', '2026-08-17 06:22:25', '<!-- wp:group {\"metadata\":{\"name\":\"Section\"},\"align\":\"full\",\"className\":\"is-style-ext-preset\\u002d\\u002dgroup\\u002d\\u002dnatural-1\\u002d\\u002dsection ext-section\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|70\",\"bottom\":\"var:preset|spacing|70\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"blockGap\":\"var:preset|spacing|55\"}},\"backgroundColor\":\"background\",\"layout\":{\"inherit\":true,\"type\":\"constrained\",\"contentSize\":\"768px\"}} -->\n<div class=\"wp-block-group alignfull is-style-ext-preset--group--natural-1--section ext-section has-background-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--70);padding-bottom:var(--wp--preset--spacing--70)\"><!-- wp:group {\"className\":\"ext-section-intro is-style-ext-preset\\u002d\\u002dgroup\\u002d\\u002dnatural-1\\u002d\\u002dsection-intro-1 has-custom-css\"} -->\n<div class=\"wp-block-group ext-section-intro is-style-ext-preset--group--natural-1--section-intro-1 has-custom-css\"><!-- wp:heading {\"className\":\"ext-animate\\u002d\\u002don\",\"style\":{\"typography\":{\"textAlign\":\"center\"}}} -->\n<h2 class=\"wp-block-heading has-text-align-center ext-animate--on\">Information We Collect on Users</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>This Privacy Policy explains how Dream Visa Guide (“we”, “us”, or “our”) collects, uses, and protects information when you visit dreamvisaguide.com (the “Site”). By using the Site, you agree to this policy.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Information we collect</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We may collect information you voluntarily provide (such as your name and email when you contact us or submit an enquiry) and information collected automatically, including your IP address, browser type, device information, pages visited, and time spent on the Site. This helps us understand how visitors use the Site and improve our content.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Cookies</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Cookies are small files stored on your device. We use cookies to remember your preferences, analyse traffic, and improve your experience. You can disable cookies in your browser settings, though some features may not work correctly as a result.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Google AdSense and third-party advertising</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We use Google AdSense to display advertisements. Google, as a third-party vendor, uses cookies (including the DoubleClick DART cookie) to serve ads based on your visits to this and other websites. Google’s use of advertising cookies enables it and its partners to serve ads to you based on your interests. You may opt out of personalised advertising by visiting Google Ads Settings (google.com/settings/ads) or www.aboutads.info. Third-party vendors and ad networks may also use cookies on the Site.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Analytics</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We may use analytics services (such as Google Analytics) to collect anonymous data about site usage. This data is aggregated and does not personally identify you.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>How we use information</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>We use collected information to respond to enquiries, provide visa guidance content, improve the Site, display relevant advertising, and comply with legal obligations. We do not sell your personal information.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Third-party links</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Our Site may contain links to external websites, including government and immigration resources. We are not responsible for the privacy practices or content of those sites.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Children’s privacy</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>The Site is not directed to children under 13, and we do not knowingly collect data from them.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Your rights &amp; consent</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>You may request access to, correction of, or deletion of your personal data by contacting us. By using this Site, you consent to this Privacy Policy. We may update this policy from time to time; changes will be posted on this page with a revised date.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Contact</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>For any questions about this Privacy Policy, contact us via the Contact Us page on dreamvisaguide.com.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->', 'Privacy Policy', '', 'publish', 'closed', 'closed', '', 'privacy-policy-2', '', '', '2026-08-25 07:17:48', '2026-08-25 07:17:48', '', 0, 'https://dreamvisaguide.com/?page_id=54', 0, 'page', '', 0),
